## Why This Is Asked
Tests knowledge of Trie data structures, deduplication strategies, and efficient prefix queries—essential skills for building autocomplete systems.

## Key Concepts
- Trie with per-node subtree counts for O(1) prefix counting
- Deduplication via global set to maintain word uniqueness
- Prefix-based retrieval with controlled result limits
- Lexicographic ordering through systematic child traversal

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Map();
    this.isWord = false;
    this.passCount = 0;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
    this.wordSet = new Set();
  }

  insert(word) {
    if (this.wordSet.has(word)) return;
    this.wordSet.add(word);
    let node = this.root;
    for (const char of word) {
      if (!node.next.has(char)) {
        node.next.set(char, new TrieNode());
      }
      node = node.next.get(char);
      node.passCount++;
    }
    node.isWord = true;
  }

  countPrefix(prefix) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return 0;
      node = node.next.get(char);
    }
    return node.passCount;
  }

  listWithPrefix(prefix, limit) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return [];
      node = node.next.get(char);
    }
    const result = [];
    this.dfs(node, prefix, result, limit);
    return result;
  }

  dfs(node, current, result, limit) {
    if (result.length >= limit) return;
    if (node.isWord) {
      result.push(current);
    }
    const sortedKeys = Array.from(node.next.keys()).sort();
    for (const char of sortedKeys) {
      this.dfs(node.next.get(char), current + char, result, limit);
    }
  }
}
```

## Why This Is Asked

Tests ability to apply DFS for topological ordering and then DP-style relaxation on a DAG to compute shortest paths without a heap. Also checks path reconstruction via a parent array.

## Key Concepts

- DFS-based topological sort
- DAG single-source shortest path via relaxation in topo order
- Path reconstruction with a parent array
- Complexity: O(n+m)

## Code Example

```javascript
function shortestPathDAG(n, edges, start, target) {
  const g = Array.from({length: n}, () => []);
  for (const [u, v, w] of edges) g[u].push([v, w]);
  const visited = Array(n).fill(false);
  const topo = [];
  function dfs(u){
    visited[u] = true;
    for (const [v] of g[u]) if (!visited[v]) dfs(v);
    topo.push(u);
  }
  for (let i = 0; i < n; i++) if (!visited[i]) dfs(i);
  topo.reverse();
  const INF = Number.POSITIVE_INFINITY;
  const dist = Array(n).fill(INF);
  const parent = Array(n).fill(-1);
  dist[start] = 0;
  for (const u of topo) {
    if (dist[u] === INF) continue;
    for (const [v, w] of g[u]) {
      if (dist[u] + w < dist[v]) {
        dist[v] = dist[u] + w;
        parent[v] = u;
      }
    }
  }
  if (dist[target] === INF) return {time: -1, path: []};
  const path = [];
  for (let x = target; x != -1; x = parent[x]) path.push(x);
  path.reverse();
  return {time: dist[target], path};
}
```

